  // ---- plexus-rt: frames over a channel ----
const rt = (() => {
// The part of a Plexus client and server that is the same for every
// activation: frames over a channel. Written by hand; a generated file
// imports it.
//
// Frames are read and written by plexus-proto's own codec, compiled to wasm
// (plexus-proto-web), never here: `Codec.load` instantiates it once, and
// every Connection and Server is handed the Codec it uses. Reading a frame
// gives its call, kind and seq, and where its body lies in the bytes; only
// the body is parsed, here, with JSON.parse.
//
// A stream is paced by credit: the activation writes an item only while the
// caller has said it will take one. An open is credit for one item. A slow
// reader slows the activation, and a reader that leaves is noticed before the
// next item.
//
// A channel is `pair()` in one page, `workerChannel` / `hostChannel` across
// a worker, or `socketChannel` over a WebSocket. A channel that can close
// says so, and every call still open on it fails with what it said.

/// A frame's kind, the digit plexus-proto writes.
const Kind = { hello: 0, open: 1, item: 2, progress: 3, end: 4, cancel: 5, credit: 6, resume: 7 }         ;

const enc = new TextEncoder(), dec = new TextDecoder();

/// plexus-proto's frame codec, running as wasm. One instance serves any
/// number of connections in a page: a read or a write is done before it
/// returns.
class Codec {
  /// What the last `read` found: the call, the seq as written (0 on a
  /// counted channel), and where the body lies in the bytes read.
  call = 0;
  seq = 0;
  start = 0;
  end = 0;
  /// Why the last `read` refused its bytes, for a person.
  error = "";
          x         ;
          at        ;
  /// The wasm's input buffer, kept while it is large enough.
          input = 0;
          room = 0;
          buf                         ;
          u8 = new Uint8Array(0);
          u32 = new Uint32Array(0);
          f64 = new Float64Array(0);

          constructor(x         ) {
    this.x = x;
    this.at = x.head();
  }

  /// Instantiate the codec from its wasm: the bytes, or a fetch of them.
  /// With neither, the wasm beside this module: fetched in a page or a
  /// worker, read from disk in Node.
  static async load(wasm                                              )                 {
    const w = await (wasm ?? beside());
    const made = w instanceof Response ? await WebAssembly.instantiateStreaming(w, {}) : await WebAssembly.instantiate(w, {});
    return new Codec(made.instance.exports                      );
  }

  /// Where `len` bytes may be written for the wasm to read.
          place(len        )         {
    if (len > this.room) {
      this.room = Math.max(len, 2 * this.room, 256);
      this.input = this.x.input(this.room);
    }
    this.views();
    return this.input;
  }

  /// The views over the wasm's memory, made again when it has grown.
          views()       {
    const b = this.x.memory.buffer;
    if (b === this.buf) return;
    this.buf = b;
    this.u8 = new Uint8Array(b);
    this.u32 = new Uint32Array(b);
    this.f64 = new Float64Array(b);
  }

  /// Read one frame: its kind, or -1 if the bytes are not a frame (`error`
  /// says why). The rest is on `call`, `seq`, `start` and `end`.
  read(bytes            )         {
    const x = this.x, at = this.place(bytes.length);
    this.u8.set(bytes, at);
    const kind = x.read(bytes.length);
    if (kind < 0) {
      this.views();
      this.error = dec.decode(this.u8.subarray(x.output(), x.output() + x.output_len()));
      return kind;
    }
    this.seq = this.f64[this.at >> 3];
    this.call = this.u32[(this.at + 8) >> 2];
    this.start = this.u32[(this.at + 12) >> 2];
    this.end = this.u32[(this.at + 16) >> 2];
    return kind;
  }

  /// The body of the frame last read from `bytes`, parsed; `undefined` for `[7]`.
  body(bytes            )       {
    return this.start === this.end ? undefined : JSON.parse(dec.decode(bytes.subarray(this.start, this.end)));
  }

  /// One frame's bytes. `body` undefined is `null`; on a counted channel an
  /// item and an end with a `null` body take their short forms.
  write(call        , kind        , body       , seq = 0, numbered = false)             {
    const text = body === undefined ? "" : JSON.stringify(body), room = text.length * 3;
    const x = this.x, at = this.place(room);
    const { written } = enc.encodeInto(text, this.u8.subarray(at, at + room));
    const n = x.write(call, kind, seq, written, numbered ? 1 : 0);
    this.views();
    const out = x.output();
    return this.u8.slice(out, out + n);
  }

  /// The seq of the next frame of `call`, of `kind`, going way `side` (0
  /// caller to activation, 1 back), as both ends of an ordered channel count it.
  count(side       , call        , kind        )         {
    return this.x.count(side, call, kind);
  }

  /// Forget every call `count` has seen: a new connection.
  reset()       {
    this.x.reset();
  }
}

async function beside()                                   {
  const at = new URL("./plexus_proto_web.wasm", import.meta.url);
  if (at.protocol !== "file:") return fetch(at);
  const fs = "node:fs/promises";   // a name, so a page never resolves it
  return (await import(fs)).readFile(at);
}

/// Bytes out, bytes in. A WebSocket, a pipe, a worker's port, or `pair()`.

/// Who sent a frame that `tap` sees.

/// Two ends of a channel in one page. `tap` sees every frame that crosses.
function pair(tap      )                     {
  const on                                 = [() => {}, () => {}];
  const end = (me       )          => ({
    send(frame) {
      tap?.(me === 0 ? "caller" : "activation", frame);
      queueMicrotask(() => on[1 - me](frame));
    },
    receive(cb) { on[me] = cb; },
  });
  return [end(0), end(1)];
}

/// A call that failed. `payload` is the method's own error, typed by the
/// generated client; `code` names it.
class PlexusFailure              extends Error {
  code        ;
  payload   ;
  constructor(code        , message        , payload   ) {
    super(message || code);
    this.code = code;
    this.payload = payload;
  }
}

/// How many items a caller says it will take before it has taken any, and
/// how many it takes before saying so again.
const WINDOW = 256, TOP_UP = 128;

/// A failure as the wire carries it: `code` the case's name and `data` its
/// value. With `failure`, the payload is the method's own error, read back
/// from `{ code: data }`, or from `code` alone for a case with no value.
function failedFrom(f      , failure                           )                {
  const payload = failure ? failure(f.data === undefined ? f.code : { [f.code]: f.data }) : f.data;
  return new PlexusFailure(f.code, f.message ?? "", payload);
}

/// The caller's end: opens calls, hands their answers back.
class Connection {
  /// The hash the activation said at `hello`.
  interface                    ;
  /// Resolves at `hello`; rejects when the activation is not the interface
  /// this client was generated from, or the channel closes first.
           ready               ;
  /// Why the channel closed, once it has. Every call then fails with it.
  closed                    ;
          calls = new Map              ();
          next = 1;
          channel         ;
          codec       ;

  constructor(channel         , codec       , expects         ) {
    this.channel = channel;
    this.codec = codec;
    let said             , refused                     ;
    this.ready = new Promise((ok, no) => { said = ok; refused = no; });
    this.ready.catch(() => {});   // a caller that never awaits `ready` is not an unhandled rejection
    channel.closed?.((why) => {
      this.closed = why;
      refused(new PlexusFailure("closed", why, undefined));
      const open = [...this.calls.values()];
      this.calls.clear();
      for (const call of open) call.fail({ code: "closed", message: why });
    });
    channel.receive((bytes) => {
      const c = this.codec, kind = c.read(bytes);
      if (kind === Kind.hello) {
        this.interface = c.body(bytes).interface;
        if (expects && expects !== this.interface) refused(new Error(`the activation's interface is ${this.interface}; this client was generated from ${expects}`));
        else said();
        return;
      }
      const call = this.calls.get(c.call);
      if (!call) return;
      if (kind === Kind.item) call.item(c.body(bytes));
      else if (kind === Kind.end) {
        this.calls.delete(c.call);
        const failure = c.body(bytes);
        failure == null ? call.end() : call.fail(failure);
      }
    });
  }

          send(id        , kind        , body       )       {
    if (this.closed === undefined) this.channel.send(this.codec.write(id, kind, body));
  }

          open(method        , params      , sink      )         {
    const id = this.next++;
    if (this.closed !== undefined) {
      sink.fail({ code: "closed", message: this.closed });
      return id;
    }
    this.calls.set(id, sink);
    this.send(id, Kind.open, Object.keys(params).length ? [method, params] : [method]);
    return id;
  }

  /// One answer: the last item before the end. Called on a stream, it reads
  /// every item, granting credit as `stream` does. `failure` turns the
  /// method's own error, as the wire carries it, into its typed value.
  call(method        , params      , failure                           )                {
    return new Promise((resolve, reject) => {
      let got      , taken = 0, done = false;
      const id = this.open(method, params, {
        item: (b) => {
          got = b;
          // The open was credit for one. Unless the end follows at once, this
          // may be a stream: grant the rest of the window, as `stream` does.
          if (++taken === 1) queueMicrotask(() => { if (!done) this.send(id, Kind.credit, WINDOW - 1); });
          else if (taken % TOP_UP === 0) this.send(id, Kind.credit, TOP_UP);
        },
        end: () => { done = true; resolve(got); },
        fail: (f) => { done = true; reject(failedFrom(f, failure)); },
      });
    });
  }

  /// Many answers. Leaving the loop early sends `cancel`.
  stream(method        , params      , failure                           )                      {
    const self = this;
    return {
      [Symbol.asyncIterator]() {
        const ready         = [];
        let done = false, failed                   , wake                          ;
        const poke = () => { wake?.(); wake = undefined; };
        const id = self.open(method, params, {
          item: (b) => { ready.push(b); poke(); },
          end: () => { done = true; poke(); },
          fail: (f) => { failed = failedFrom(f, failure); done = true; poke(); },
        });
        self.send(id, Kind.credit, WINDOW - 1);   // the open itself carries credit for one
        let taken = 0;
        return {
          async next() {
            while (!ready.length && !done) await new Promise      ((ok) => { wake = ok; });
            if (ready.length) {
              // Every few items taken, say the activation may write that many more.
              if (++taken % TOP_UP === 0 && !done) self.send(id, Kind.credit, TOP_UP);
              return { value: ready.shift(), done: false };
            }
            if (failed) throw failed;
            return { value: undefined, done: true };
          },
          async return() {
            if (!done) { done = true; self.calls.delete(id); self.send(id, Kind.cancel); }
            return { value: undefined, done: true };
          },
        };
      },
    };
  }
}

/// The activation's end: reads `open`, runs the method, writes what it answers.
class Server {
          methods = new Map                 ();
  /// For each stream that is running: the items it may still write, and who is waiting to.
          streams = new Map                                                              ();
          channel         ;
          codec       ;

  constructor(channel         , codec       ) {
    this.channel = channel;
    this.codec = codec;
    channel.receive((bytes) => {
      const c = this.codec, kind = c.read(bytes);
      if (kind === Kind.open) {
        const [name, params] = c.body(bytes);
        return void this.run(c.call, name, params ?? {});
      }
      const s = this.streams.get(c.call);
      if (!s) return;
      if (kind === Kind.cancel) s.gone = true;
      else if (kind === Kind.credit) s.credit += c.body(bytes);
      else return;
      s.wake?.();
    });
    // Nobody is left to read: every stream stops at its next item.
    channel.closed?.(() => {
      for (const s of this.streams.values()) { s.gone = true; s.wake?.(); }
    });
  }

  /// Say which interface this is. The first frame of a connection.
  hello(hash        )       {
    this.channel.send(this.codec.write(0, Kind.hello, { interface: hash }));
  }

  method(name        , run                       , failure                             = (p) => p)       {
    this.methods.set(name, { stream: false, run, failure });
  }

  stream(name        , run                       , failure                             = (p) => p)       {
    this.methods.set(name, { stream: true, run, failure });
  }

  /// Say what is served at `at`: `<at>._ir` answers its IR and `<at>._hash`
  /// its hash, and `_tree` lists every place something is served.
  describe(at        , ir      )       {
    this.mounts.push(at);
    this.method(at + "._ir", () => ir);
    this.method(at + "._hash", () => ir.hash);
  }

  /// Hold an activation that lives at the far end of another channel, as a
  /// child at `at`. Every call under `at` is passed on, and its answers
  /// passed back; this side never learns the child's interface.
  remote(at        , far            , farAt        )       {
    this.mounts.push(at);
    this.passes.push({ at: at + ".", run: (rest, params) => far.stream(farAt + "." + rest, params) });
  }

          mounts           = [];
          passes                                                                              = [];

          find(name        )                      {
    if (name === "_tree") return { stream: false, run: () => this.mounts, failure: (p) => p };
    const own = this.methods.get(name);
    if (own) return own;
    const pass = this.passes.find((p) => name.startsWith(p.at));
    // A call passed on is read as a stream: one answer is a stream of one.
    return pass && { stream: true, run: (params) => pass.run(name.slice(pass.at.length), params), failure: (p) => p };
  }

          async run(id        , name        , params      )                {
    const m = this.find(name);
    const send = (kind        , body       ) => this.channel.send(this.codec.write(id, kind, body));
    if (!m) return send(Kind.end, { code: "not-found", message: `no method ${name}` });
    try {
      if (m.stream) {
        // An open carries credit for one item, so a call with one answer needs no credit frame.
        const s = { credit: 1, gone: false, wake: undefined                             };
        this.streams.set(id, s);
        try {
          for await (const item of await m.run(params)) {
            // Write only while the caller will take it; wait for credit otherwise.
            while (s.credit === 0 && !s.gone) await new Promise      ((ok) => { s.wake = ok; });
            if (s.gone) return;                       // leaving the loop drops the stream
            s.credit--;
            send(Kind.item, item);
          }
        } finally {
          this.streams.delete(id);
        }
      } else {
        const answer = await m.run(params);
        if (answer !== undefined) send(Kind.item, answer);
      }
      send(Kind.end);
    } catch (e     ) {
      // A method's own error arrives as `e.payload`; anything else is the
      // activation's fault. A case is written as its name, the code, and its
      // value, the data, as the Rust end writes it.
      // A failure from a call passed on is passed back as it came.
      if (e instanceof PlexusFailure) return send(Kind.end, { code: e.code, message: e.message === e.code ? undefined : e.message, data: e.payload });
      if (!(e && e.payload !== undefined)) return send(Kind.end, { code: "internal", message: String(e?.message ?? e) });
      const error = m.failure(e.payload);
      const [code, data] = typeof error === "string" ? [error, undefined]
        : error && typeof error === "object" && Object.keys(error).length === 1 ? Object.entries(error)[0] : ["failed", error];
      send(Kind.end, { code, data });
    }
  }
}

/// A channel's receiving half: frames that arrive before anyone listens are
/// kept, and so is a close that comes before anyone asks.
function inbox() {
  let on                                       , onClosed                                     ;
  let kept               = [], why                    ;
  return {
    put(f            ) { on ? on(f) : kept.push(f); },
    close(reason        ) {
      if (why !== undefined) return;
      why = reason;
      onClosed?.(reason);
    },
    receive(cb                         ) {
      on = cb;
      for (const f of kept) cb(f);
      kept = [];
    },
    closed(cb                       ) { why !== undefined ? cb(why) : (onClosed = cb); },
  };
}

/// A frame's own buffer, to be handed over whole: transferred, not copied.
function own(frame            )              {
  const whole = frame.byteOffset === 0 && frame.byteLength === frame.buffer.byteLength && frame.buffer instanceof ArrayBuffer;
  return (whole ? frame : frame.slice()).buffer               ;
}

/// The page's end of a channel to an activation served in `worker`.
/// `tap` sees each frame before it is handed over: read it then, not later.
///
/// A worker's messages that arrive before it listens are lost, and its
/// module may still be loading when the page first sends; so frames wait
/// here until `hostChannel` says, with an empty message, that it listens.
function workerChannel(worker        , tap      )          {
  const box = inbox();
  let waiting                            = [];
  const post = (b             ) => worker.postMessage(b, [b]);
  worker.addEventListener("message", (e) => {
    if (waiting) {
      for (const b of waiting) post(b);
      waiting = undefined;
      return;
    }
    const f = new Uint8Array(e.data);
    tap?.("activation", f);
    box.put(f);
  });
  // A worker that fails before it listens will never answer. An error after
  // that is the worker's to report: it still runs.
  worker.addEventListener("error", (e) => {
    if (waiting) box.close(e.message ? `the worker failed to start: ${e.message}` : "the worker failed to start");
  });
  return {
    send(frame) {
      tap?.("caller", frame);
      const b = own(frame);
      waiting ? waiting.push(b) : post(b);
    },
    receive: box.receive,
    closed: box.closed,
  };
}

/// Inside a worker, its end of the channel to the page that started it
/// (`workerChannel`). It listens from the moment it is called, and keeps
/// what arrives until the server takes it:
///
///     const server = new Server(hostChannel(), await Codec.load());
///     serveKiln(kiln, server);
///     server.hello(KilnClient.interface);
function hostChannel()          {
  const scope = globalThis                   , box = inbox();
  scope.addEventListener("message", (e) => box.put(new Uint8Array(e.data)));
  scope.postMessage(new ArrayBuffer(0), []);   // listening: the page may send
  return {
    send(frame) {
      const b = own(frame);
      scope.postMessage(b, [b]);
    },
    receive: box.receive,
  };
}

/// A channel over a WebSocket: a URL to connect to, or a socket already made
/// (a page's, Node's, or the `ws` package's on a server). Frames are sent as
/// binary messages and read from binary or text; those sent before the
/// socket opens wait for it. `tap` is for the caller's end.
function socketChannel(to                          , tap      )                                  {
  const socket = typeof to === "string" || to instanceof URL ? new WebSocket(to) : to, box = inbox();
  const waiting          = [];
  socket.binaryType = "arraybuffer";
  socket.addEventListener("open", () => { for (const f of waiting.splice(0)) socket.send(f); });
  socket.addEventListener("message", (e) => {
    const f = typeof e.data === "string" ? enc.encode(e.data) : new Uint8Array(e.data);
    tap?.("activation", f);
    box.put(f);
  });
  socket.addEventListener("close", (e) => box.close(`the WebSocket closed (${e.code}${e.reason ? ": " + e.reason : ""})`));
  return {
    socket,
    send(frame) {
      tap?.("caller", frame);
      if (socket.readyState === WebSocket.CONNECTING) waiting.push(frame         );
      else if (socket.readyState === WebSocket.OPEN) socket.send(frame         );
    },
    receive: box.receive,
    closed: box.closed,
  };
}

/// Bytes as a value is written: base64, padded (plexus-proto `value`).
function b64(bytes            )         {
  let text = "";
  for (let i = 0; i < bytes.length; i += 0x8000) text += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(text);
}
const unb64 = (text        ) => Uint8Array.from(atob(text), (c) => c.charCodeAt(0));

/// Each item of a stream through `f`.
async function* each      (items                                              , f             )                   {
  for await (const a of await items) yield f(a);
}
return { Kind, Codec, pair, PlexusFailure, WINDOW, Connection, Server, workerChannel, hostChannel, socketChannel, b64, unb64, each };
})();

  // ---- plexus-rt's store: the page gives the engine, the worker opens the store, the import itself ----
const store = (() => {
// An activation's store in a page: the import plexus:store/sql, answered in
// the activation's worker by the one SQLite engine (../plexus/engine) the
// page fetched and compiled once.
//
// In the page, before anything else listens to the worker:
//
//     const worker = give(new Worker("./kiln-worker.js", { type: "module" }), "kiln");
//
// In the worker, before the activation's first call:
//
//     const store = await openStore({ keep: ["kiln"] });
//
// The activation's component is turned into JavaScript with its import
// mapped here (`jco transpile --map 'plexus:store/sql=plexus-rt/store'`):
// `open`, `execute` and `query` below are what it calls.
//
// A component's imports are synchronous, so the engine runs in the worker
// that calls it: fetched and compiled once a page, instantiated once a
// worker. The page names the activation a worker runs, and every database
// name is scoped by it: `kiln` opened by the glaze is `glaze/kiln`, not the
// kiln's. One storing activation a worker.

/// The engine's three core modules, by the names its JavaScript asks for.
const CORES = ["sqlite.core.wasm", "sqlite.core2.wasm", "sqlite.core3.wasm"]         ;

/// What a page gives a worker: the engine's core modules, compiled, and
/// where its JavaScript is (absent when the application carries it, and
/// hands the worker its `instantiate`).

/// jco's `instantiate` for the engine (`--instantiation async`).

/// A database's name, and an activation's: letters, digits, `_`, `-` and
/// `.`, not first. Each is a file's or a directory's name, so nothing in it
/// reaches another directory.
const PLAIN = /^[A-Za-z0-9_-][A-Za-z0-9_.-]*$/;

function plain(what        , name        )         {
  if (!PLAIN.test(name)) throw refusal(`${what} ${JSON.stringify(name)}: letters, digits, \`_\`, \`-\` and \`.\`, not first`);
  return name;
}

/// An error as the component reads it: its `payload` is the `err` it gets.
function refusal(message        )        {
  return Object.assign(new Error(message), { payload: message });
}

// ---- the page's side ----

const fetched = new Map                         ();

/// The engine, compiled once a page: fetched from the directory `at` names
/// (by default the one this module is in, where `npm run build` puts it),
/// or compiled from the bytes of its core modules, which an application
/// that carries the engine itself passes, by name, with no `glue`.
function loadEngine(at                                              = new URL("./", import.meta.url))                  {
  if (typeof at !== "string" && !(at instanceof URL)) {
    const bytes = at;
    return Promise.all(CORES.map((n) => WebAssembly.compile(bytes[n]))).then((ms) => ({ modules: byName(ms) }));
  }
  const dir = new URL(at, location.href);
